// 多字段不变量（余额 + 流水）不能只靠 Atomic，
// 必须用锁/事务或不可变状态整体替换。

public Product get(long id) {
    String key = "product:" + id;
    Product cached = redis.get(key);
    if (cached != null) return cached;

    String lock = "lock:product:" + id;
    if (redis.setIfAbsent(lock, "1", Duration.ofSeconds(3))) {
        try {
            Product db = repository.findById(id).orElse(null);
            if (db == null) {
                redis.set(key, NULL_PLACEHOLDER, Duration.ofSeconds(30));
                return null;
            }
            redis.set(key, db, Duration.ofMinutes(10));
            return db;
        } finally {
            redis.delete(lock);
        }
    }
    // 未拿到锁：短暂等待/直接回源，避免无限自旋
    return repository.findById(id).orElse(null);
}

