function validateOrderPayload(payload) {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return { valid: false, errors: ["payload"] };
  }
  const errors = [];
  if (typeof payload.customerId !== "string" || !payload.customerId.trim()) {
    errors.push("customerId");
  }
  const items = Array.isArray(payload.items) ? payload.items : [];
  if (!Array.isArray(payload.items) || items.length < 1 || items.length > 20) {
    errors.push("items");
  }
  items.forEach((item, index) => {
    if (!item || typeof item !== "object") {
      errors.push("items[" + index + "]");
      return;
    }
    if (!Number.isInteger(item.quantity) || item.quantity < 1 || item.quantity > 99) {
      errors.push("items[" + index + "].quantity");
    }
    if (!Number.isInteger(item.unitPriceCents) || item.unitPriceCents < 0) {
      errors.push("items[" + index + "].unitPriceCents");
    }
  });
  return { valid: errors.length === 0, errors };
}

