codeChallenges.solutionCode:
function buildOrderPage(filters, page = 1, pageSize = 20) {
  const input = filters && typeof filters === "object" ? filters : {};
  const safePage = Number.isInteger(page) && page > 0 ? page : 1;
  const safeSize = Number.isInteger(pageSize)
    ? Math.min(100, Math.max(1, pageSize))
    : 20;
  const clauses = ["1=1"];
  const params = [];

  if (typeof input.status === "string" && input.status.trim()) {
    clauses.push("status = ?");
    params.push(input.status.trim());
  }
  if (Number.isInteger(input.minTotalCents) && input.minTotalCents >= 0) {
    clauses.push("total_cents >= ?");
    params.push(input.minTotalCents);
  }
  const sql = "SELECT id, user_id, status, total_cents FROM orders WHERE " +
    clauses.join(" AND ") + " ORDER BY id LIMIT ? OFFSET ?";
  params.push(safeSize, (safePage - 1) * safeSize);
  return { sql, params, page: safePage, pageSize: safeSize };
}

