codeChallenges.solutionCode:
function simulatePool(tasks, config) {
  const list = Array.isArray(tasks) ? tasks : [];
  const core = Number.isInteger(config?.core) && config.core > 0 ? config.core : 1;
  const max = Number.isInteger(config?.max) && config.max >= core ? config.max : core;
  const queueCap = Number.isInteger(config?.queue) && config.queue >= 0 ? config.queue : 0;
  let threads = 0;
  let queued = 0;
  let accepted = 0;
  let rejected = 0;

  for (let i = 0; i < list.length; i += 1) {
    if (threads < core) {
      threads += 1;
      accepted += 1;
    } else if (queued < queueCap) {
      queued += 1;
      accepted += 1;
    } else if (threads < max) {
      threads += 1;
      accepted += 1;
    } else {
      rejected += 1;
    }
  }
  return { accepted, rejected, activeThreads: threads, queued };
}

