codeChallenges.solutionCode:
function allowRequests(timestamps, now, limit, windowMs) {
  if (!Array.isArray(timestamps)) return false;
  if (!Number.isInteger(limit) || limit <= 0) return false;
  if (!Number.isInteger(windowMs) || windowMs <= 0) return false;
  const start = now - windowMs;
  const count = timestamps.filter((time) => time > start && time <= now).length;
  return count < limit;
}

