codeChallenges.solutionCode:
function mergeTopK(shards, k) {
  if (!Array.isArray(shards) || !Number.isInteger(k) || k <= 0) return [];
  const merged = [];
  for (const shard of shards) {
    if (Array.isArray(shard)) merged.push(...shard.map((item) => ({ ...item })));
  }
  merged.sort((a, b) => (b.score - a.score) || a.id.localeCompare(b.id));
  return merged.slice(0, k);
}
